/* Canonical calendar and operational status rules. Agent mirror is generated by sync-rules.mjs. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.LabCalendar=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  function valid(d){return typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d+'T00:00:00Z'))&&new Date(d+'T00:00:00Z').toISOString().slice(0,10)===d;}
  function dayContext(date,cfg){
    cfg=cfg||{};
    const special=(cfg.specialDays||[]).find(x=>x.date===date);
    const source=special&&valid(special.teachingDate)?special.teachingDate:date;
    const week=valid(cfg.termStart)&&source>=cfg.termStart?Math.floor((Date.parse(source)-Date.parse(cfg.termStart))/604800000)+1:null;
    return {date,teachingDate:source,weekday:valid(source)?new Date(source+'T00:00:00Z').getUTCDay():null,weekNo:week,
      holiday:special?special.isTeachingDay===false:(cfg.holidays||[]).includes(date),
      coverage:!valid(cfg.termStart)||!valid(cfg.termEnd)?'unknown':date<cfg.termStart||date>cfg.termEnd?'out_of_range':'complete'};
  }
  function matches(w,n){w=w||{};return n===null||(!(n<Number(w.from||1)||n>Number(w.to||99))&&!(w.parity==='odd'&&n%2===0)&&!(w.parity==='even'&&n%2===1));}
  function effective(date,ctx){
    const cfg=ctx.sysConfig||ctx.term||{}, dc=dayContext(date,cfg), rooms=[...(ctx.labs||[]),...(ctx.openLabs||[])];
    if(dc.holiday||dc.coverage==='out_of_range')return [];
    return (ctx.timetable||[]).filter(t=>t&&t.status!=='cancelled'&&(!t.term||!cfg.term||t.term===cfg.term)&&Number(t.weekday)===dc.weekday&&matches(t.weeks,dc.weekNo)).map(t=>{
      const row=Object.assign({},t);let cancelled=false;
      (ctx.scheduleAdjust||[]).filter(a=>a&&a.status!=='revoked'&&a.date===date&&a.timetableId===t.id).forEach(a=>{
        if(a.action==='cancel')cancelled=true;
        if(a.action==='move'){if(a.toLabId)row.labId=a.toLabId;if(a.toPeriodKey)row.periodKey=a.toPeriodKey;}
        row.adjustmentId=a.id;
      });
      const lab=rooms.find(l=>l.id===row.labId);if(lab)row.labName=lab.name;
      return cancelled?null:row;
    }).filter(Boolean);
  }
  function stats(rows){
    const activities=new Set(),classes=new Set(),slots=new Set(),groups={};let records=0;
    rows.forEach(r=>{const names=r.classNames&&r.classNames.length?r.classNames:r.className?[r.className]:[''];records+=names.length;
      names.filter(Boolean).forEach(n=>classes.add(n));activities.add(r.id);slots.add(r.periodKey);
      const key=(r.labId||r.labName)+':'+r.periodKey;(groups[key]||(groups[key]=new Set())).add(r.id);
    });
    return {recordCount:records,activityCount:activities.size,classCount:classes.size,occupiedPeriodCount:slots.size,
      conflicts:Object.entries(groups).filter(x=>x[1].size>1).map(x=>({slot:x[0],activityIds:Array.from(x[1]),status:'needs_verification'}))};
  }
  function roomState(room,ctx,date,period){
    const closures=(ctx.roomClosures||[]).filter(c=>(c.roomId===room.id||c.roomId===room.name)&&c.status!=='revoked'&&c.startDate<=date&&c.endDate>=date&&(!period||!(c.periodKeys||[]).length||(c.periodKeys||[]).includes(period)));
    const rows=effective(date,ctx).filter(t=>(t.labId===room.id||t.labName===room.name)&&(!period||t.periodKey===period));
    const dc=dayContext(date,ctx.sysConfig||ctx.term||{});
    return {roomId:room.id,roomName:room.name,door:room.status==='active'?'open':room.status==='closed'?'closed':'unknown',
      service:room.status==='inactive'||closures.length?'suspended':'normal',
      schedule:rows.length?'occupied':dc.coverage==='complete'&&(ctx.timetable||[]).length?'no_scheduled_class':'unknown',
      presence:'unknown',keyStatus:((ctx.keys||[]).find(k=>k.labId===room.id)||{}).status||'unknown',closures,stats:stats(rows)};
  }
  function inspectionSummary(records,rooms,date){
    const ids=new Set((rooms||[]).map(r=>r.id)),latest=new Map();
    (records||[]).filter(r=>r.kind==='field_inspection'&&r.date===date&&ids.has(r.roomId)&&Array.isArray(r.checklist)&&r.checklist.length).sort((a,b)=>String(a.submittedAt).localeCompare(String(b.submittedAt))).forEach(r=>latest.set(r.roomId,r));
    let complete=0,abnormal=0,checked=0,total=0;
    latest.forEach(r=>{let all=true;r.checklist.forEach(c=>{total++;if(c.state==='done'||c.state==='abnormal')checked++;else all=false;if(c.state==='abnormal')abnormal++;});if(all)complete++;});
    return {status:!latest.size?'not_started':abnormal?'abnormal':complete===ids.size&&ids.size?'completed':'partial',
      roomCount:ids.size,recordedRooms:latest.size,completedRooms:complete,abnormalCount:abnormal,checkedItems:checked,totalItems:total,
      completionRate:total?Math.round(checked/total*100):null,accuracy:null,lastAt:latest.size?Array.from(latest.values()).map(r=>r.submittedAt).sort().at(-1):null};
  }
  function inspectionRows(records,rooms){
    return (records||[]).map(r=>{
      if(r.kind!=='field_inspection')return Object.assign({},r,{results:r.results||[],statusLabel:'历史记录（未纳入现场统计）'});
      const checks=r.checklist||[],bad=checks.filter(c=>c.state==='abnormal').length,all=checks.length&&checks.every(c=>c.state==='done');
      const room=(rooms||[]).find(x=>x.id===r.roomId);
      return Object.assign({},r,{time:r.submittedAt,inspector:r.actorId,hasAbnormal:bad>0,abnormalCount:bad,
        statusLabel:bad?'异常':all?'已确认完成':'部分确认',results:checks.map(c=>({labName:room?room.name:r.roomId,status:c.state==='abnormal'?'异常':c.state==='done'?'已完成':'未确认',remark:c.label+'；'+(r.note||'')}))});
    }).sort((a,b)=>String(b.time).localeCompare(String(a.time)));
  }
  function dutyWindow(period,mode,minutes){
    if(!period||!['checkin','checkout'].includes(mode))return {valid:false,msg:'请选择合法值班节次与操作'};
    const toMin=s=>{const p=s.split(':').map(Number);return p[0]*60+p[1];},start=toMin(period.start),end=toMin(period.end);
    if(mode==='checkin'){
      if(minutes<start-30)return {valid:false,msg:'尚未到最早签到时间，请稍等'};
      if(minutes>end)return {valid:false,msg:'已超过本节签到截止时间'};
      return {valid:true,status:minutes>start+10?'补签到':'签到'};
    }
    if(minutes<end)return {valid:false,msg:'尚未到最早签退时间，请稍等'};
    if(minutes>end+60)return {valid:false,msg:'已超过签退补签截止时间，请联系管理员'};
    return {valid:true,status:minutes>end+20?'补签退':'签退'};
  }
  return {inspectionRows,dutyWindow,valid,dayContext,effective,stats,roomState,inspectionSummary};
});
